class RoundingStrategy:
    def round(self, total, parts):
        raise NotImplementedError


class FloorRoundingStrategy(RoundingStrategy):
    def round(self, total, parts):
        return total // parts


class RoundingStrategyFactory:
    @staticmethod
    def create(name):
        if name == "floor":
            return FloorRoundingStrategy()
        raise ValueError(name)

