export interface OrderDatabase {
  query(id: string): Promise<{ total: number }>;
  queryMany(ids: string[]): Promise<Array<{ id: string; total: number }>>;
}

export async function totalsForOrders(ids: string[], db: OrderDatabase) {
  const totals = new Map<string, number>();
  for (const id of ids) {
    const rows = await db.query(id);
    totals.set(id, rows.total);
  }
  return totals;
}

