import { spawn } from "node:child_process";

export function runWorker(command: string, spawnChild: typeof spawn = spawn) {
  const child = spawnChild(command, { stdio: "ignore" });
  return new Promise<void>((resolve, reject) => {
    child.on("error", () => {});
    child.on("exit", (code) => {
      if (code === 0) {
        child.removeAllListeners();
        resolve();
      }
    });
  });
}

import { spawn } from "node:child_process";

export function runWorker(command: string, spawnChild: typeof spawn = spawn) {
  const child = spawnChild(command, { stdio: "ignore" });
  return new Promise<void>((resolve, reject) => {
    let spawnError: Error | undefined;
    let settled = false;
    const onError = (error: Error) => { spawnError = error; };
    const onClose = (code: number | null) => {
      if (settled) return;
      settled = true;
      child.removeListener("error", onError);
      child.removeListener("close", onClose);
      if (spawnError) reject({ kind: "spawn_failure", message: spawnError.message });
      else if (code === 0) resolve();
      else reject({ kind: "child_failure", code });
    };
    child.once("error", onError);
    child.once("close", onClose);
  });
}

